import sys, json

class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        pos = neg = 0
        k = 0
        while target:
            target, remainder = divmod(target, x)
            if k:
                pos, neg = (
                    min(remainder * k + pos, (remainder + 1) * k + neg),
                    min((x - remainder) * k + pos,
                        (x - remainder - 1) * k + neg)
                )
            else:
                pos, neg = remainder * 2, (x - remainder) * 2
            k += 1
        return min(pos, k + neg) - 1

