#include <stdio.h>

int leastOpsExpressTarget(int x, int target) {
    int pos = 0, neg = 0, k = 0;
    while (target > 0) {
        int remainder = target % x;
        target /= x;
        if (k > 0) {
            int a = remainder * k + pos;
            int b = (remainder + 1) * k + neg;
            int newPos = a < b ? a : b;
            a = (x - remainder) * k + pos;
            b = (x - remainder - 1) * k + neg;
            int newNeg = a < b ? a : b;
            pos = newPos;
            neg = newNeg;
        } else {
            pos = remainder * 2;
            neg = (x - remainder) * 2;
        }
        k++;
    }
    int answer = pos < k + neg ? pos : k + neg;
    return answer - 1;
}

int main(void) {
    int x, target;
    if (scanf("[%d,%d]", &x, &target) == 2) {
        printf("%d\n", leastOpsExpressTarget(x, target));
    }
    return 0;
}

